SELECT

FROM SYS_THIRDPARTY_AUTH
WHERE
LOGIC_DEL = 0

    AND AUTH_ID = #{dto.authId}


    AND SOURCE = #{dto.source}


    AND OPEN_ID = #{dto.openId}


    AND USER_NAME = #{dto.userName}


    AND NICK_NAME = #{dto.nickName}


    AND EMAIL = #{dto.email}


    AND AVATAR = #{dto.avatar}


    AND ACCESS_TOKEN = #{dto.accessToken}


    AND EXPIRE_TIMEOUT = #{dto.expireTimeout}


    AND REFRESH_TOKEN = #{dto.refreshToken}


    AND ACCESS_CODE = #{dto.accessCode}


    AND UNION_ID = #{dto.unionId}


    AND SCOPE = #{dto.scope}


    AND TOKEN_TYPE = #{dto.tokenType}


    AND ID_TOKEN = #{dto.idToken}


    AND MAC_ALGORITHM = #{dto.macAlgorithm}


    AND MAC_KEY = #{dto.macKey}


    AND CODE = #{dto.code}


    AND OAUTH_TOKEN = #{dto.oauthToken}


    AND OAUTH_TOKEN_SECRET = #{dto.oauthTokenSecret}

ORDER BY create_time DESC

